"use strict";(self.webpackChunkpersonalweb=self.webpackChunkpersonalweb||[]).push([[4710],{66262:(t,n)=>{n.A=(t,n)=>{const r=t.__vccOpts||t;for(const[t,o]of n)r[t]=o;return r}},72971:(t,n,r)=>{r.r(n),r.d(n,{comp:()=>g,data:()=>d});var o=r(20641);const s={},g=(0,r(66262).A)(s,[["render",function(t,n){return(0,o.uX)(),(0,o.CE)("div",null,n[0]||(n[0]=[(0,o.Fv)('<h1 id="芯片制造原理" tabindex="-1"><a class="header-anchor" href="#芯片制造原理"><span>芯片制造原理</span></a></h1><h3 id="_1️⃣-原料提纯制晶圆" tabindex="-1"><a class="header-anchor" href="#_1️⃣-原料提纯制晶圆"><span>1️⃣ 原料提纯制晶圆</span></a></h3><ol><li><p><strong>原料采集</strong></p><ul><li>选取 <strong>高二氧化硅含量</strong> 的天然石英砂。</li><li>通过 <strong>2000 ℃ 以上</strong> 的高温熔炼，去除杂质，得到 <strong>粗硅</strong>（纯度约 <strong>98 %</strong>）。</li></ul></li><li><p><strong>西门子法提纯</strong></p><ul><li>粗硅在 <strong>氢氟酸</strong> 环境下转化为 <strong>氯硅烷（SiHCl₃）</strong> 气体。</li><li>气体在 <strong>高温（≈ 1100 ℃）</strong> 下分解，沉积出 <strong>多晶硅</strong>，纯度 <strong>接近 100 %</strong>。</li></ul></li><li><p><strong>单晶硅棒生长（直拉法）</strong></p><ul><li>将多晶硅熔融后，使用 <strong>单晶种子</strong> 缓慢向上拉伸，形成直径 <strong>300 mm</strong>、重量 <strong>≈ 200 kg</strong> 的 <strong>单晶硅棒</strong>。</li><li>拉伸过程受 <strong>温度梯度</strong> 与 <strong>拉速</strong> 严格控制，以确保晶格缺陷最小。</li></ul></li><li><p><strong>晶圆切割与抛光</strong></p><ul><li>单晶硅棒经 <strong>金刚石线切割</strong> 切成 <strong>200 mm–300 mm</strong> 的薄片（晶圆）。</li><li>随后进行 <strong>化学机械抛光（CMP）</strong>，使晶圆表面达到 <strong>原子级平整度</strong>（粗糙度 &lt; 0.5 nm）。</li></ul></li></ol><blockquote><p><strong>小贴士</strong>：在晶圆切割前常会进行 <strong>硅片清洗（RCA 清洗）</strong>，去除金属离子与有机残留，提升后续工艺良率。</p></blockquote><hr><h3 id="_2️⃣-晶圆前处理" tabindex="-1"><a class="header-anchor" href="#_2️⃣-晶圆前处理"><span>2️⃣ 晶圆前处理</span></a></h3><table><thead><tr><th>步骤</th><th>目的</th><th>关键设备/材料</th></tr></thead><tbody><tr><td><strong>热氧化</strong></td><td>在晶圆表面形成 <strong>几纳米厚的二氧化硅（SiO₂）</strong> 绝缘层</td><td>氧化炉（高温 900‑1100 ℃）</td></tr><tr><td><strong>清洗</strong></td><td>去除氧化过程产生的颗粒与离子</td><td>RCA 清洗、HF 浸蚀</td></tr><tr><td><strong>薄膜沉积</strong></td><td>为后续光刻提供 <strong>光刻胶（Photoresist）</strong> 附着层</td><td>低压化学气相沉积（LPCVD）或原子层沉积（ALD）</td></tr><tr><td><strong>烘烤（软烤）</strong></td><td>使光刻胶预硬化，提升图形分辨率</td><td>烘箱（≈ 90 ℃）</td></tr></tbody></table><blockquote><p><strong>工序概览</strong>：从晶圆进入工厂到完成前处理，通常需要 <strong>&gt; 1000 道工序</strong>，耗时 <strong>≈ 3 个月</strong>，每一步都必须在 <strong>洁净度 10⁻⁹ m³</strong> 的无尘车间完成。</p></blockquote><hr><h3 id="_3️⃣-euv-光刻核心" tabindex="-1"><a class="header-anchor" href="#_3️⃣-euv-光刻核心"><span>3️⃣ EUV 光刻核心</span></a></h3><h4 id="_3-1-设备概览" tabindex="-1"><a class="header-anchor" href="#_3-1-设备概览"><span>3.1 设备概览</span></a></h4><ul><li><strong>厂商</strong>：荷兰 <strong>ASML</strong></li><li><strong>型号</strong>：NXE:3400B（代表 13 nm EUV 波长）</li><li><strong>模组数量</strong>：7 大模组（光源、照明、掩模、投影、检测、对准、控制）</li></ul><h4 id="_3-2-工作原理" tabindex="-1"><a class="header-anchor" href="#_3-2-工作原理"><span>3.2 工作原理</span></a></h4><ol><li><p><strong>光源模组</strong></p><ul><li>两束 <strong>高功率激光（≈ 20 kW）</strong> 同时击中 <strong>液态锡滴</strong>，产生 <strong>等离子体</strong>。</li><li>等离子体发出 <strong>波长 13.5 nm</strong> 的 <strong>极紫外光（EUV）</strong>。</li></ul></li><li><p><strong>照明光学模组</strong></p><ul><li>通过 <strong>多层镜面（Mo/Si 多层膜）</strong> 将 EUV 光聚焦并均匀化，形成 <strong>均匀光斑</strong>。</li></ul></li><li><p><strong>光掩膜（Mask）</strong></p><ul><li>掩膜上刻有 <strong>电路图案</strong>（光学密度差异），采用 <strong>光刻胶</strong> 覆盖的 <strong>石英基板</strong>。</li><li>掩膜与晶圆 <strong>亚纳米级对准</strong>（误差 &lt; 5 原子）。</li></ul></li><li><p><strong>投影光学模组</strong></p><ul><li>采用 <strong>四倍缩小</strong>（4×）的 <strong>投影系统</strong>，将掩膜图案投射到 <strong>光刻胶</strong> 上。</li><li>通过 <strong>双晶圆平台</strong>（交替曝光与测量），实现 <strong>每块晶圆 18 s</strong> 完成一次曝光。</li></ul></li><li><p><strong>后处理</strong></p><ul><li>曝光后进行 <strong>显影</strong>，显影液溶解未受光照的光刻胶，形成 <strong>图形</strong>。</li><li>随后进行 <strong>干法刻蚀（RIE）</strong> 或 <strong>湿法刻蚀</strong>，将图形转移到硅或氧化层上。</li></ul></li></ol><h4 id="_3-3-关键技术指标" tabindex="-1"><a class="header-anchor" href="#_3-3-关键技术指标"><span>3.3 关键技术指标</span></a></h4><table><thead><tr><th>指标</th><th>数值</th><th>说明</th></tr></thead><tbody><tr><td><strong>波长</strong></td><td>13.5 nm</td><td>极紫外光，显著降低衍射极限</td></tr><tr><td><strong>数值孔径（NA）</strong></td><td>0.55 ~ 0.65</td><td>决定分辨率的关键参数</td></tr><tr><td><strong>曝光时间</strong></td><td>18 s / 块</td><td>双晶圆平台交替工作</td></tr><tr><td><strong>对准误差</strong></td><td>&lt; 5 原子</td><td>通过 <strong>干涉仪</strong> 与 <strong>光学测距</strong> 实时校正</td></tr></tbody></table><hr><h3 id="_4️⃣-后续加工与封装" tabindex="-1"><a class="header-anchor" href="#_4️⃣-后续加工与封装"><span>4️⃣ 后续加工与封装</span></a></h3><table><thead><tr><th>阶段</th><th>主要工序</th><th>目的</th><th>关键材料/设备</th></tr></thead><tbody><tr><td><strong>显影 &amp; 刻蚀</strong></td><td>显影 → 干法刻蚀 → 湿法刻蚀</td><td>将光刻图形转移到硅层或介质层</td><td>显影液、等离子体刻蚀机</td></tr><tr><td><strong>离子注入（掺杂）</strong></td><td>磷（n 型）/ 硼（p 型）离子注入</td><td>调节晶体管阈值电压</td><td>离子注入机、退火炉</td></tr><tr><td><strong>沉积</strong></td><td>化学气相沉积（CVD）/ 原子层沉积（ALD）</td><td>形成栅氧化层、金属互连层</td><td>SiO₂、Si₃N₄、Cu、TaN</td></tr><tr><td><strong>金属化</strong></td><td>铜互连（Dual‑Damascene）</td><td>连接晶体管形成电路</td><td>Cu‑沉积、化学机械抛光</td></tr><tr><td><strong>晶圆切割</strong></td><td>刀片切割（Dicing）</td><td>将晶圆分割为 <strong>裸片（die）</strong></td><td>金刚石刀片、超声波切割</td></tr><tr><td><strong>封装</strong></td><td>粘合、焊线、环氧树脂封装、散热盖</td><td>保护芯片、提供电气/热接口</td><td>球栅阵列（BGA）、倒装芯片（COB）</td></tr><tr><td><strong>测试 &amp; 编码</strong></td><td>功能测试、激光刻码</td><td>确认良率、追溯</td><td>自动测试设备（ATE）、激光刻码机</td></tr></tbody></table><h4 id="_4️⃣1-结构层数与尺寸" tabindex="-1"><a class="header-anchor" href="#_4️⃣1-结构层数与尺寸"><span>4️⃣1. 结构层数与尺寸</span></a></h4><ul><li><strong>层数</strong>：现代高端芯片 <strong>&gt; 100 层</strong>（包括金属层、介质层、栅层）。</li><li><strong>最小特征尺寸</strong>：<strong>3 nm</strong>（FinFET/Gate‑All‑Around）——对应 <strong>晶体管栅宽</strong> 约 <strong>3 nm</strong>。</li><li><strong>单颗芯片晶体管数量</strong>：<strong>≈ 1 × 10¹²</strong>（千亿）</li></ul><h4 id="_4️⃣2-封装技术趋势" tabindex="-1"><a class="header-anchor" href="#_4️⃣2-封装技术趋势"><span>4️⃣2. 封装技术趋势</span></a></h4><table><thead><tr><th>技术</th><th>说明</th><th>代表产品</th></tr></thead><tbody><tr><td><strong>2.5D/3D 堆叠</strong></td><td>通过硅通孔（TSV）实现芯片垂直互连</td><td>AMD EPYC 7003、Intel Xeon 3D</td></tr><tr><td><strong>Chip‑on‑Wafer‑on‑Substrate (CoWoS)</strong></td><td>将多芯片直接粘合在同一硅片上</td><td>NVIDIA HGX</td></tr><tr><td><strong>Fan‑Out Wafer Level Packaging (FOWLP)</strong></td><td>无基板直接封装，提升散热与尺寸</td><td>Apple A14 BGA‑F</td></tr></tbody></table><hr><h3 id="_5️⃣-关键挑战与前沿研究" tabindex="-1"><a class="header-anchor" href="#_5️⃣-关键挑战与前沿研究"><span>5️⃣ 关键挑战与前沿研究</span></a></h3><table><thead><tr><th>挑战</th><th>现状</th><th>研究方向</th></tr></thead><tbody><tr><td><strong>光源功率</strong></td><td>EUV 光源功率 <strong>≈ 250 W</strong>（单束）</td><td>提升至 <strong>&gt; 500 W</strong>，降低曝光时间</td></tr><tr><td><strong>掩模缺陷</strong></td><td>掩模成本 <strong>&gt; 10 M USD</strong>，缺陷极易导致整片报废</td><td><strong>自适应掩模修复（AMR）</strong> 与 <strong>AI 检测</strong></td></tr><tr><td><strong>散热</strong></td><td>高功率芯片功耗 <strong>&gt; 300 W/cm²</strong></td><td><strong>微流体冷却</strong>、<strong>相变材料</strong></td></tr><tr><td><strong>良率</strong></td><td>先进节点良率 <strong>≈ 70 %</strong></td><td><strong>机器学习预测缺陷</strong>、<strong>全息光刻</strong></td></tr><tr><td><strong>材料极限</strong></td><td>传统 SiO₂/SiN 介质在 3 nm 规模出现漏电</td><td><strong>高‑κ/金属栅</strong>、<strong>二维材料（MoS₂、Graphene）</strong></td></tr></tbody></table><hr><h3 id="_6️⃣-小结" tabindex="-1"><a class="header-anchor" href="#_6️⃣-小结"><span>6️⃣ 小结</span></a></h3><ol><li><strong>原料提纯 → 单晶硅棒 → 晶圆</strong>：从自然矿石到原子级平整的硅片，经历多道化学与物理提纯。</li><li><strong>前处理</strong>：形成绝缘层、光刻胶等，为后续光刻做好准备。</li><li><strong>EUV 光刻</strong>：利用 13.5 nm 极紫外光实现 <strong>亚 10 nm</strong> 级别的图形转移，是现代芯片微缩的核心技术。</li><li><strong>后续加工</strong>：通过掺杂、沉积、金属化等步骤构建 <strong>百层以上</strong> 的三维电路结构。</li><li><strong>封装与测试</strong>：将裸片转化为可商用的 <strong>封装芯片</strong>，并通过严格测试确保功能与可靠性。</li></ol><blockquote><p><strong>展望</strong>：随着 <strong>EUV 光源功率</strong>、<strong>AI‑驱动缺陷检测</strong> 与 <strong>新材料</strong> 的突破，未来的芯片有望突破 <strong>2 nm</strong> 甚至 <strong>1 nm</strong> 级别，实现更高的计算密度与能效。</p></blockquote><hr><p><em>此笔记基于《[[芯片制造原理]]》进行扩充，加入了工艺细节、关键参数、技术挑战及前沿趋势，供学习、复习或撰写技术报告时参考。</em></p>',32)]))}]]),d=JSON.parse('{"path":"/zh/posts/daily/%E8%8A%AF%E7%89%87%E5%88%B6%E9%80%A0%E5%8E%9F%E7%90%86.html","title":"芯片制造原理","lang":"zh-CN","frontmatter":{"icon":"pen-to-square","date":"2026-05-19T00:00:00.000Z","category":["Learning Records"],"tag":["Notes"],"description":"芯片制造原理 1️⃣ 原料提纯制晶圆 原料采集 选取 高二氧化硅含量 的天然石英砂。 通过 2000 ℃ 以上 的高温熔炼，去除杂质，得到 粗硅（纯度约 98 %）。 西门子法提纯 粗硅在 氢氟酸 环境下转化为 氯硅烷（SiHCl₃） 气体。 气体在 高温（≈ 1100 ℃） 下分解，沉积出 多晶硅，纯度 接近 100 %。 单晶硅棒生长（直拉法） 将...","head":[["meta",{"property":"og:url","content":"https://crc011220.github.io/zh/posts/daily/%E8%8A%AF%E7%89%87%E5%88%B6%E9%80%A0%E5%8E%9F%E7%90%86.html"}],["meta",{"property":"og:site_name","content":"Ruochen Chen"}],["meta",{"property":"og:title","content":"芯片制造原理"}],["meta",{"property":"og:description","content":"芯片制造原理 1️⃣ 原料提纯制晶圆 原料采集 选取 高二氧化硅含量 的天然石英砂。 通过 2000 ℃ 以上 的高温熔炼，去除杂质，得到 粗硅（纯度约 98 %）。 西门子法提纯 粗硅在 氢氟酸 环境下转化为 氯硅烷（SiHCl₃） 气体。 气体在 高温（≈ 1100 ℃） 下分解，沉积出 多晶硅，纯度 接近 100 %。 单晶硅棒生长（直拉法） 将..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-05-19T13:34:38.000Z"}],["meta",{"property":"article:tag","content":"Notes"}],["meta",{"property":"article:published_time","content":"2026-05-19T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-05-19T13:34:38.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"芯片制造原理\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-05-19T00:00:00.000Z\\",\\"dateModified\\":\\"2026-05-19T13:34:38.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Ruochen Chen\\"}]}"]]},"headers":[{"level":3,"title":"1️⃣ 原料提纯制晶圆","slug":"_1️⃣-原料提纯制晶圆","link":"#_1️⃣-原料提纯制晶圆","children":[]},{"level":3,"title":"2️⃣ 晶圆前处理","slug":"_2️⃣-晶圆前处理","link":"#_2️⃣-晶圆前处理","children":[]},{"level":3,"title":"3️⃣ EUV 光刻核心","slug":"_3️⃣-euv-光刻核心","link":"#_3️⃣-euv-光刻核心","children":[]},{"level":3,"title":"4️⃣ 后续加工与封装","slug":"_4️⃣-后续加工与封装","link":"#_4️⃣-后续加工与封装","children":[]},{"level":3,"title":"5️⃣ 关键挑战与前沿研究","slug":"_5️⃣-关键挑战与前沿研究","link":"#_5️⃣-关键挑战与前沿研究","children":[]},{"level":3,"title":"6️⃣ 小结","slug":"_6️⃣-小结","link":"#_6️⃣-小结","children":[]}],"git":{"createdTime":1779197678000,"updatedTime":1779197678000,"contributors":[{"name":"Ruochen Chen","email":"ruocchen1220@gmail.com","commits":1}]},"readingTime":{"minutes":5.45,"words":1636},"filePathRelative":"zh/posts/daily/芯片制造原理.md","localizedDate":"2026年5月19日","excerpt":"\\n<h3>1️⃣ 原料提纯制晶圆</h3>\\n<ol>\\n<li>\\n<p><strong>原料采集</strong></p>\\n<ul>\\n<li>选取 <strong>高二氧化硅含量</strong> 的天然石英砂。</li>\\n<li>通过 <strong>2000 ℃ 以上</strong> 的高温熔炼，去除杂质，得到 <strong>粗硅</strong>（纯度约 <strong>98 %</strong>）。</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>西门子法提纯</strong></p>\\n<ul>\\n<li>粗硅在 <strong>氢氟酸</strong> 环境下转化为 <strong>氯硅烷（SiHCl₃）</strong> 气体。</li>\\n<li>气体在 <strong>高温（≈ 1100 ℃）</strong> 下分解，沉积出 <strong>多晶硅</strong>，纯度 <strong>接近 100 %</strong>。</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>单晶硅棒生长（直拉法）</strong></p>\\n<ul>\\n<li>将多晶硅熔融后，使用 <strong>单晶种子</strong> 缓慢向上拉伸，形成直径 <strong>300 mm</strong>、重量 <strong>≈ 200 kg</strong> 的 <strong>单晶硅棒</strong>。</li>\\n<li>拉伸过程受 <strong>温度梯度</strong> 与 <strong>拉速</strong> 严格控制，以确保晶格缺陷最小。</li>\\n</ul>\\n</li>\\n<li>\\n<p><strong>晶圆切割与抛光</strong></p>\\n<ul>\\n<li>单晶硅棒经 <strong>金刚石线切割</strong> 切成 <strong>200 mm–300 mm</strong> 的薄片（晶圆）。</li>\\n<li>随后进行 <strong>化学机械抛光（CMP）</strong>，使晶圆表面达到 <strong>原子级平整度</strong>（粗糙度 &lt; 0.5 nm）。</li>\\n</ul>\\n</li>\\n</ol>","autoDesc":true}')}}]);